  /* ---------- precalculus-review ---------- */
  N["precalculus-review-skill-01"] = {"obj": "factor polynomials completely and simplify rational expressions before doing calculus with them", "idea": "Factor out the GCF first, then look for a pattern; a factor that appears on top and bottom of a fraction cancels only when it multiplies everything.", "voc": [["greatest common factor (GCF)", "The largest factor every term shares, such as 2x in 4x² + 6x."], ["difference of squares", "a² − b² = (a − b)(a + b)."], ["sum or difference of cubes", "a³ ± b³ = (a ± b)(a² ∓ ab + b²)."]], "watch": "Canceling terms instead of factors: (x² + 3)/x is not x + 3.", "cards": [{"h": "Factoring in order", "big": "Always pull out the {{GCF}} first. Then try a trinomial, a difference of squares, cubes, or grouping.", "steps": ["⟨x^2 - 8x + 15⟩: two numbers with product 15 and sum −8 are ⟨{{-3}}⟩ and ⟨-5⟩, so ⟨(x - 3)(x - 5)⟩.", "⟨27x^3 - 27 = 27(x^3 - 1) = {{27(x - 1)(x^2 + x + 1)}}⟩.", "Grouping: ⟨x^3 + 2x^2 + 6x + 12 = x^2(x + 2) + 6(x + 2) = {{(x + 2)(x^2 + 6)}}⟩."]}]};
  N["precalculus-review-skill-02"] = {"obj": "evaluate, rewrite and solve exponential expressions and equations, including those with base e", "idea": "Exponent rules let you combine powers of the same base; to solve, write both sides with the same base or take a logarithm.", "voc": [["base e", "The number e ≈ 2.718, the base of natural growth."], ["exponential function", "f(x) = abˣ with b > 0, b ≠ 1."]], "watch": "Multiplying the base instead of the exponent, as in (e²)³ = e⁵ (it is e⁶).", "cards": [{"h": "Same base, equal exponents", "big": "If ⟨b^u = b^v⟩ then ⟨u = v⟩. Rewrite each side as a power of the {{same base}}.", "steps": ["⟨5^{x - 4} = 25 = 5^2⟩, so ⟨x - 4 = 2⟩ and ⟨x = {{6}}⟩.", "⟨e^{4x} \\div e^{2x} = {{e^{2x}}}⟩ because exponents subtract when dividing.", "When the bases cannot match, take ⟨\\ln⟩ of both sides: ⟨e^{3x} = 31⟩ gives ⟨x = \\tfrac{1}{3}\\ln 31⟩."]}]};
  N["precalculus-review-skill-03"] = {"obj": "evaluate logarithms and use the properties of logarithms to expand, condense and solve", "idea": "A logarithm is an exponent: log_b(N) = k means bᵏ = N. ln is log base e.", "voc": [["logarithm", "The exponent you put on a base to get a number."], ["natural logarithm", "ln x = logₑ x."], ["power property", "ln(Mᵖ) = p·ln M."]], "watch": "Writing ln(M + N) = ln M + ln N; the product rule is ln(MN) = ln M + ln N.", "cards": [{"h": "Logs undo exponents", "big": "⟨\\log_b N = k⟩ means ⟨b^k = N⟩. So ⟨\\ln 1 = {{0}}⟩ and ⟨\\ln e = 1⟩.", "steps": ["⟨\\log_2 8 = {{3}}⟩ because ⟨2^3 = 8⟩.", "Expand: ⟨\\ln\\frac{x^2}{y^5} = 2\\ln x - {{5\\ln y}}⟩.", "Condense: ⟨4\\ln x - \\ln 4 = \\ln\\frac{x^4}{4}⟩."]}]};
  N["precalculus-review-skill-04"] = {"obj": "find exact values of the six trigonometric functions at special angles in degrees and radians", "idea": "On the unit circle, the point at angle θ is (cos θ, sin θ); a reference angle and the quadrant give every special value.", "voc": [["unit circle", "The circle of radius 1 centered at the origin."], ["reference angle", "The acute angle between the terminal side and the x-axis."], ["radian", "The angle that cuts off an arc equal to the radius; π radians = 180°."]], "watch": "Using the wrong sign for the quadrant, such as sin(16π/3) = +√3/2 (it is −√3/2).", "cards": [{"h": "Reference angle, then sign", "big": "Find the {{reference angle}}, read the value from the first quadrant, then attach the sign for the quadrant (All, Sine, Tangent, Cosine).", "steps": ["⟨\\tan 120°⟩: reference angle 60°, Quadrant II where tangent is negative, so ⟨{{-\\sqrt{3}}}⟩.", "⟨\\cos(-\\pi)⟩: the point at ⟨-\\pi⟩ is ⟨(-1, 0)⟩, so ⟨\\cos(-\\pi) = {{-1}}⟩.", "⟨\\sec\\tfrac{\\pi}{4} = \\frac{1}{\\cos(\\pi/4)} = \\sqrt{2}⟩."]}]};
  N["precalculus-review-skill-05"] = {"obj": "move between graphs, tables and formulas and compute average rates of change", "idea": "The average rate of change on [a, b] is the slope of the secant line: (f(b) − f(a))/(b − a), whatever form f is given in.", "voc": [["average rate of change", "(f(b) − f(a))/(b − a), the slope between two points."], ["secant line", "The line through two points of a graph."]], "watch": "Forgetting to divide by b − a, or subtracting the outputs in one order and the inputs in the other.", "cards": [{"h": "Slope between two points", "big": "Average rate of change ⟨= \\frac{f(b) - f(a)}{b - a}⟩: the {{slope}} of the secant line.", "steps": ["⟨f(x) = -x^2 + 4x⟩ on ⟨[1, 7]⟩: ⟨\\frac{f(7) - f(1)}{7 - 1} = \\frac{-21 - 3}{6} = {{-4}}⟩.", "From a table with ⟨f(2) = 31⟩ and ⟨f(4) = -20⟩: ⟨\\frac{-20 - 31}{4 - 2} = {{-\\tfrac{51}{2}}}⟩."]}]};
  /* ---------- limits-continuity ---------- */
  N["limits-continuity-skill-01"] = {"obj": "read and write limit notation, including one-sided and infinite limits", "idea": "lim (x → a) f(x) = L says f(x) gets as close to L as we like when x is close enough to a; it says nothing about f(a) itself.", "voc": [["limit", "The value f(x) approaches as x approaches a."], ["one-sided limit", "A limit from the left (x → a⁻) or the right (x → a⁺)."], ["infinite limit", "f(x) grows without bound, written lim f(x) = ∞; the limit does not exist as a number."]], "watch": "Reading lim (x → a) f(x) as the value f(a).", "cards": [{"h": "Reading limit notation", "big": "⟨\\lim_{x \\to a} f(x) = L⟩ describes what f {{approaches}} near ⟨a⟩, not its value at ⟨a⟩.", "steps": ["⟨\\lim_{x \\to 5^+} f(x) = -7⟩: as x approaches 5 from the {{right}}, f(x) approaches −7.", "⟨\\lim_{x \\to 4} f(x) = \\infty⟩: f grows without bound near 4, so x = 4 is a {{vertical asymptote}}.", "For a polynomial, substitution works: ⟨\\lim_{x \\to 3}(2x^2 + 5x + 5) = 38⟩."]}]};
  N["limits-continuity-skill-02"] = {"obj": "estimate limits from graphs and from tables of values on both sides of a point", "idea": "Read the y-value the graph heads toward from each side; in a table, use the values closest to a, not the farthest ones.", "voc": [["open circle", "A point the graph approaches but does not include."], ["two-sided limit", "Exists only when the left and right limits are equal."]], "watch": "Using f(a) (the solid dot) instead of where the graph is heading.", "cards": [{"h": "Left, right, then compare", "big": "Find the {{left-hand}} and right-hand limits separately. The two-sided limit exists only if they {{match}}.", "steps": ["Table: ⟨f(-2.01) \\approx 1.99⟩, ⟨f(-1.99) \\approx 2.01⟩, so ⟨\\lim_{x \\to -2} f(x) = {{2}}⟩.", "Graph: from the left −2, from the right −1, so the limit {{does not exist}}, whatever the solid dot shows."]}]};
  N["limits-continuity-skill-03"] = {"obj": "evaluate limits algebraically by substitution, factoring, rationalizing and combining fractions", "idea": "Try direct substitution first. A result of 0/0 means more algebra is needed: cancel the common factor, then substitute again.", "voc": [["indeterminate form", "0/0 (or ∞/∞): substitution does not decide the limit."], ["removable factor", "A factor that cancels from the top and bottom."]], "watch": "Treating 0/0 as 0, or as \"does not exist\".", "cards": [{"h": "0/0 means factor and cancel", "big": "If substitution gives ⟨\\frac{0}{0}⟩, {{factor}} and cancel the common factor; the limit of what remains is the answer.", "steps": ["⟨\\lim_{x \\to -3}\\frac{x^2 - 9}{x + 3} = \\lim_{x \\to -3}(x - 3) = {{-6}}⟩.", "⟨\\lim_{x \\to 2}\\frac{x^3 - 8}{x - 2} = \\lim_{x \\to 2}(x^2 + 2x + 4) = {{12}}⟩.", "⟨\\lim_{x \\to 0}\\frac{\\sin(3x)}{x} = 3⟩, using ⟨\\lim_{x \\to 0}\\frac{\\sin x}{x} = 1⟩."]}]};
  N["limits-continuity-skill-04"] = {"obj": "find one-sided and two-sided limits of piecewise functions and infinite one-sided limits", "idea": "Each one-sided limit uses only the piece of the function on that side of a.", "voc": [["piecewise function", "A function defined by different formulas on different intervals."], ["left-hand limit", "lim (x → a⁻), using x < a."]], "watch": "Plugging a into the wrong piece, or adding the two sides together.", "cards": [{"h": "One piece per side", "big": "Left limit: use the piece for ⟨x < a⟩. Right limit: use the piece for ⟨x \\ge a⟩. Equal values mean the {{two-sided}} limit exists.", "steps": ["⟨f(x) = -3x - 1⟩ for ⟨x < -3⟩: ⟨\\lim_{x \\to -3^-} f(x) = -3(-3) - 1 = {{8}}⟩.", "⟨\\lim_{x \\to 2^+}\\frac{-2}{(x - 2)^2}⟩: the bottom is a tiny positive number, so the limit is {{negative infinity}}."]}]};
  N["limits-continuity-skill-05"] = {"obj": "use limits at infinity and infinite limits to describe end behavior and asymptotes", "idea": "For rational functions, the highest powers decide the limit at infinity: equal degrees give the ratio of leading coefficients, a bigger bottom gives 0.", "voc": [["horizontal asymptote", "y = L where lim (x → ±∞) f(x) = L."], ["vertical asymptote", "x = a where f(x) → ±∞ as x → a."], ["end behavior", "What f(x) does as x → ±∞."]], "watch": "Using the constant terms, or assuming every limit at infinity is 0.", "cards": [{"h": "Compare the degrees", "big": "As ⟨x \\to \\infty⟩ only the {{leading terms}} matter.", "steps": ["⟨\\lim_{x \\to \\infty}\\frac{6x^3 - 3x^2 + 3}{5x^3 - 1} = {{\\tfrac{6}{5}}}⟩ (equal degrees).", "⟨\\lim_{x \\to \\infty}\\frac{-6x}{4x^3} = {{0}}⟩ (bottom-heavy).", "⟨\\lim_{x \\to \\infty}\\frac{x^3 - 3x^2 + 5}{x - 3} = \\infty⟩ (top-heavy)."]}]};
  N["limits-continuity-skill-06"] = {"obj": "use the three-part definition of continuity to test a point and to find intervals of continuity", "idea": "f is continuous at a when f(a) exists, the limit exists, and they are equal; a parameter can be chosen to make the pieces meet.", "voc": [["continuous at a", "lim (x → a) f(x) = f(a)."], ["continuous on an interval", "Continuous at every point of the interval."]], "watch": "Checking only that f(a) exists, or only that the two pieces have the same slope.", "cards": [{"h": "Make the pieces meet", "big": "At the break point, set the left piece equal to the right piece and solve for the {{parameter}}.", "steps": ["⟨3x + 2⟩ for ⟨x < -1⟩ and ⟨3x + k⟩ for ⟨x \\ge -1⟩: ⟨-1 = -3 + k⟩, so ⟨k = {{2}}⟩.", "⟨2x^2 + x⟩ for ⟨x < 3⟩ and ⟨kx + 2⟩: ⟨21 = 3k + 2⟩, so ⟨k = {{\\tfrac{19}{3}}}⟩."]}]};
  N["limits-continuity-skill-07"] = {"obj": "classify discontinuities as removable, jump or infinite and locate holes", "idea": "A factor that cancels gives a hole (removable); a factor left in the denominator gives a vertical asymptote (infinite); unequal one-sided limits give a jump.", "voc": [["removable discontinuity", "A hole: the limit exists but f(a) is missing or different."], ["jump discontinuity", "The one-sided limits exist but are different."], ["infinite discontinuity", "f(x) → ±∞ near a."]], "watch": "Using a zero of the numerator as the hole, or giving the hole a y-value of 0.", "cards": [{"h": "Find the hole", "big": "Factor, cancel the common factor, and substitute into what remains to get the hole’s {{y-value}}.", "steps": ["⟨\\frac{x^2 + 7x + 10}{x + 2} = x + 5⟩ for ⟨x \\ne -2⟩, so the hole is at ⟨({{-2}}, 3)⟩.", "⟨\\frac{2x^2 - 6x}{x^2 - 5x} = \\frac{2(x - 3)}{x - 5}⟩: hole at ⟨x = 0⟩ with ⟨y = \\tfrac{6}{5}⟩; ⟨x = 5⟩ is a {{vertical asymptote}}."]}]};
  N["limits-continuity-skill-08"] = {"obj": "apply the Intermediate Value Theorem and the Extreme Value Theorem and state their conditions", "idea": "Continuity on a closed interval is the key hypothesis: the IVT guarantees every value between f(a) and f(b), and the EVT guarantees an absolute maximum and minimum.", "voc": [["Intermediate Value Theorem", "If f is continuous on [a, b], it takes every value between f(a) and f(b)."], ["Extreme Value Theorem", "If f is continuous on [a, b], it has an absolute max and min there."]], "watch": "Using the IVT to count solutions exactly; it only guarantees at least as many as there are sign changes.", "cards": [{"h": "Count the guaranteed solutions", "big": "Each pair of consecutive table values on opposite sides of the target guarantees {{at least one}} solution between them.", "steps": ["f(2) = 6, f(5) = −4, f(7) = 5, f(9) = −4, target −3: three sign changes, so the IVT guarantees at least {{3}} solutions.", "f(x) = 1/(x − 1/2) on [−2, 3]: not {{continuous}} at x = 1/2, so the EVT does not apply."]}]};
